pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz: any address (caller) and any amount for the grant.
    // General rule: after calling newGrantProposal(recipient, amount), proposalCount increases by exactly 1.
    function testFuzz_property(address caller, address recipient, uint256 amount) public {
        // keep addresses in normal range (not zero for caller to allow vm.prank to be meaningful)
        if (caller == address(0)) caller = address(1);
        // record before
        uint before = c.proposalCount();
        // act as caller
        vm.prank(caller);
        c.newGrantProposal(recipient, amount);
        uint after = c.proposalCount();
        // single assertion: proposalCount increased by exactly 1 on the correct contract; the mutant may violate this
        assertTrue(after == before + 1);
    }
}

