pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz the recipient address and an arbitrary amount. The general rule:
    // After a call to newGrantProposal(recipient, amount), c.proposalCount() must have increased by exactly 1
    // from its previous value. The mutant that moves the increment will sometimes leave a different value.
    function testFuzz_property(address recipient, uint256 amount) public {
        // Keep domain wide — disallow the zero address only if we want to ensure mapping behavior is meaningful.
        // But the reference handles address(0) as a valid recipient; so do not assume. We only need a wide domain.
        // Record current proposalCount
        uint256 before = c.proposalCount();

        // Call newGrantProposal as the fuzzed caller (prank) to simulate varied msg.senders
        vm.prank(msg.sender);
        c.newGrantProposal(recipient, amount);

        // Exactly one assertion: the proposalCount getter must equal before + 1.
        // The reference always increments by 1 on every call; the mutant increments after writing and
        // emits a different value in its event, and its stored proposalCount observed after the call
        // can differ (off-by-one) for some inputs; the fuzzer will find inputs that make the mutant fail.
        assertTrue(c.proposalCount() == before + 1);
    }
}

